import { test, expect } from '@playwright/test';

test.describe('Protected Page Authentication', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should redirect to login when accessing a protected page without authentication', async ({ page }) => {
    // Verify the protected page loads
    const protectedPageContent = page.getByRole('heading', { name: /Dashboard/i });
    await expect(protectedPageContent).toBeVisible();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Verify login form is present
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Verify login form has required fields
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Verify login button is enabled
    await expect(loginButton).toBeEnabled();

    // Attempt to submit the form without filling in required fields
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify user is redirected to login page
    const loginPageTitle = page.getByRole('heading', { name: /login/i });
    await expect(loginPageTitle).toBeVisible();

    // Verify login page has error message
    const errorMessage = page.getByText(/please fill all fields/i);
    await expect(errorMessage).toBeVisible();

    // Verify login button is now disabled
    await expect(loginButton).not.toBeEnabled();
  });

  test('should allow access to protected page after successful login', async ({ page }) => {
    // Verify protected page loads
    const protectedPageContent = page.getByRole('heading', { name: /Dashboard/i });
    await expect(protectedPageContent).toBeVisible();

    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Verify login form is present
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();

    // Verify login form has required fields
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toBeVisible();
    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toBeVisible();

    // Verify login button is enabled
    await expect(loginButton).toBeEnabled();

    // Fill in login form with valid credentials
    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('user@example.com');

    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('password123');

    // Submit login form
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify user is redirected to protected page
    const protectedPageContent = page.getByRole('heading', { name: /Dashboard/i });
    await expect(protectedPageContent).toBeVisible();

    // Verify user is logged in
    const welcomeMessage = page.getByText(/welcome, user/i);
    await expect(welcomeMessage).toBeVisible();

    // Verify user can interact with protected page
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).toBeVisible();

    // Verify dashboard content is displayed
    const dashboardContent = page.getByText(/dashboard content/i);
    await expect(dashboardContent).toBeVisible();

    // Verify user is not redirected back to login
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).not.toBeVisible();
  });
});
